import React, { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../Context/AuthContext';

// 💡 커스텀 모달 컴포넌트 (alert/confirm 대체) - 기존 코드 유지
const CustomModal = ({ message, onConfirm, onCancel, showCancel = false }) => {
    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white p-6 rounded-lg shadow-xl max-w-sm w-full text-center">
                <p className="text-lg mb-6">{message}</p>
                <div className="flex justify-center space-x-4">
                    <button
                        onClick={onConfirm}
                        className="px-5 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition"
                    >
                        확인
                    </button>
                    {showCancel && (
                        <button
                            onClick={onCancel}
                            className="px-5 py-2 bg-gray-300 text-gray-800 rounded-md hover:bg-gray-400 transition"
                        >
                            취소
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
};

function ReviewDetail() {
    const { reviewId } = useParams();
    const navigate = useNavigate();
    const { isAuthenticated, user, token } = useAuth(); // 인증 정보 사용
    const [review, setReview] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    // 이미지 모달 관련 상태 - 기존 코드 유지
    const [showImageModal, setShowImageModal] = useState(false);
    const [modalImageUrl, setModalImageUrl] = useState('');
    const [modalImageDescription, setModalImageDescription] = useState('');

    // ====================================================================================
    // 💡💡💡 댓글 기능 관련 상태 추가 시작 💡💡💡
    // ====================================================================================
    const [comments, setComments] = useState([]); // 댓글 목록
    const [newCommentContent, setNewCommentContent] = useState(''); // 새 댓글 내용
    const [editingCommentId, setEditingCommentId] = useState(null); // 현재 수정 중인 댓글 ID
    const [editingCommentContent, setEditingCommentContent] = useState(''); // 수정 중인 댓글 내용
    const [commentCurrentPage, setCommentCurrentPage] = useState(0); // 댓글 현재 페이지
    const [commentTotalPages, setCommentTotalPages] = useState(0); // 댓글 전체 페이지 수

    const [showCommentModal, setShowCommentModal] = useState(false); // 댓글 관련 모달 표시 여부
    const [commentModalMessage, setCommentModalMessage] = useState(''); // 댓글 관련 모달 메시지
    const [onCommentModalConfirm, setOnCommentModalConfirm] = useState(() => () => {}); // 댓글 모달 확인 액션
    const [onCommentModalCancel, setOnCommentModalCancel] = useState(() => () => {}); // 댓글 모달 취소 액션
    const [showCommentModalCancel, setShowCommentModalCancel] = useState(false); // 댓글 모달 취소 버튼 표시 여부
    // ====================================================================================
    // 💡💡💡 댓글 기능 관련 상태 추가 끝 💡💡💡
    // ====================================================================================

    // 이미지 모달 핸들러 - 기존 코드 유지
    const handleImageClick = (imageUrl, description) => {
        setModalImageUrl(imageUrl);
        setModalImageDescription(description);
        setShowImageModal(true);
    };

    const handleCloseImageModal = () => {
        setShowImageModal(false);
        setModalImageUrl('');
        setModalImageDescription('');
    };

    // 리뷰 상세 정보 불러오기 - 기존 코드 유지
    useEffect(() => {
        const fetchReview = async () => {
            try {
                const response = await axios.get(`/api/reviews/${reviewId}`);
                setReview(response.data);
            } catch (err) {
                setError('리뷰 정보를 불러오는데 실패했습니다.');
                console.error('Error fetching review:', err);
            } finally {
                setLoading(false);
            }
        };
        fetchReview();
    }, [reviewId]);


    // ====================================================================================
    // 💡💡💡 댓글 기능 관련 함수 추가 시작 💡💡💡
    // ====================================================================================

    // 댓글 목록 불러오기
    const fetchComments = useCallback(async () => {
        try {
            const response = await axios.get(`/api/reviews/${reviewId}/comments`, {
                params: {
                    page: commentCurrentPage,
                    size: 10, // 페이지 당 댓글 수
                    sortBy: 'createdAt',
                    sortOrder: 'desc'
                }
            });
            setComments(response.data.content);
            setCommentTotalPages(response.data.totalPages);
        } catch (err) {
            console.error('댓글을 불러오는데 실패했습니다:', err);
            setCommentModalMessage('댓글을 불러오는데 실패했습니다.');
            setShowCommentModal(true);
            setShowCommentModalCancel(false);
            setOnCommentModalConfirm(() => () => setShowCommentModal(false));
        }
    }, [reviewId, commentCurrentPage]);

    // reviewId나 commentCurrentPage가 변경될 때마다 댓글 불러오기
    useEffect(() => {
        if (reviewId) {
            fetchComments();
        }
    }, [reviewId, commentCurrentPage, fetchComments]); // fetchComments를 의존성 배열에 추가하여 useCallback의 효과를 유지

    // 새 댓글 작성 핸들러
    const handleCommentSubmit = async (e) => {
        e.preventDefault();
        if (!newCommentContent.trim()) {
            setCommentModalMessage('댓글 내용을 입력해주세요.');
            setShowCommentModal(true);
            setShowCommentModalCancel(false);
            setOnCommentModalConfirm(() => () => setShowCommentModal(false));
            return;
        }

        if (!isAuthenticated || !token) {
            setCommentModalMessage('로그인 후 댓글을 작성할 수 있습니다.');
            setShowCommentModal(true);
            setShowCommentModalCancel(false);
            setOnCommentModalConfirm(() => () => {
                setShowCommentModal(false);
                navigate('/login'); // 로그인 페이지로 이동
            });
            return;
        }

        try {
            await axios.post(`/api/reviews/${reviewId}/comments`, {
                reviewId: reviewId, // DTO에 reviewId 포함
                content: newCommentContent
            }, {
                headers: {
                    'Authorization': `Bearer ${token}`
                }
            });
            setNewCommentContent(''); // 댓글 입력창 초기화
            setCommentCurrentPage(0); // 새 댓글 작성 시 첫 페이지로 이동하여 최신 댓글 보이게
            fetchComments(); // 댓글 다시 불러오기
            setCommentModalMessage('댓글이 성공적으로 등록되었습니다! 🥳');
            setShowCommentModal(true);
            setShowCommentModalCancel(false);
            setOnCommentModalConfirm(() => () => setShowCommentModal(false));
        } catch (err) {
            console.error('댓글 등록 실패:', err);
            const errorMessage = err.response?.data || '댓글 등록 중 오류가 발생했습니다.';
            setCommentModalMessage(`댓글 등록 실패: ${errorMessage}`);
            setShowCommentModal(true);
            setShowCommentModalCancel(false);
            setOnCommentModalConfirm(() => () => setShowCommentModal(false));
        }
    };

    // 댓글 수정 버튼 클릭 핸들러
    const handleEditClick = (comment) => {
        setEditingCommentId(comment.reviewCommentId);
        setEditingCommentContent(comment.content);
    };

    // 댓글 수정 취소 핸들러
    const handleCancelEdit = () => {
        setEditingCommentId(null);
        setEditingCommentContent('');
    };

    // 댓글 수정 제출 핸들러
    const handleEditSubmit = async (commentId) => {
        if (!editingCommentContent.trim()) {
            setCommentModalMessage('수정할 내용을 입력해주세요.');
            setShowCommentModal(true);
            setShowCommentModalCancel(false);
            setOnCommentModalConfirm(() => () => setShowCommentModal(false));
            return;
        }

        if (!isAuthenticated || !token) {
            setCommentModalMessage('로그인 후 댓글을 수정할 수 있습니다.');
            setShowCommentModal(true);
            setShowCommentModalCancel(false);
            setOnCommentModalConfirm(() => () => {
                setShowCommentModal(false);
                navigate('/login');
            });
            return;
        }

        try {
            await axios.put(`/api/reviews/${reviewId}/comments/${commentId}`, {
                reviewCommentId: commentId,
                reviewId: reviewId, // DTO에 reviewId 포함
                content: editingCommentContent
            }, {
                headers: {
                    'Authorization': `Bearer ${token}`
                }
            });
            setEditingCommentId(null); // 수정 모드 종료
            setEditingCommentContent(''); // 수정 내용 초기화
            fetchComments(); // 댓글 다시 불러오기
            setCommentModalMessage('댓글이 성공적으로 수정되었습니다! ✍️');
            setShowCommentModal(true);
            setShowCommentModalCancel(false);
            setOnCommentModalConfirm(() => () => setShowCommentModal(false));
        } catch (err) {
            console.error('댓글 수정 실패:', err);
            const errorMessage = err.response?.data || '댓글 수정 중 오류가 발생했습니다.';
            setCommentModalMessage(`댓글 수정 실패: ${errorMessage}`);
            setShowCommentModal(true);
            setShowCommentModalCancel(false);
            setOnCommentModalConfirm(() => () => setShowCommentModal(false));
        }
    };

    // 댓글 삭제 핸들러
    const handleDeleteClick = (commentId) => {
        setCommentModalMessage('정말로 이 댓글을 삭제하시겠습니까?');
        setShowCommentModal(true);
        setShowCommentModalCancel(true);
        setOnCommentModalConfirm(() => async () => {
            setShowCommentModal(false); // 모달 닫기
            if (!isAuthenticated || !token) {
                setCommentModalMessage('로그인 후 댓글을 삭제할 수 있습니다.');
                setShowCommentModal(true);
                setShowCommentModalCancel(false);
                setOnCommentModalConfirm(() => () => {
                    setShowCommentModal(false);
                    navigate('/login');
                });
                return;
            }
            try {
                await axios.delete(`/api/reviews/${reviewId}/comments/${commentId}`, {
                    headers: {
                        'Authorization': `Bearer ${token}`
                    }
                });
                fetchComments(); // 댓글 다시 불러오기
                setCommentModalMessage('댓글이 성공적으로 삭제되었습니다! 🗑️');
                setShowCommentModal(true);
                setShowCommentModalCancel(false);
                setOnCommentModalConfirm(() => () => setShowCommentModal(false));
            } catch (err) {
                console.error('댓글 삭제 실패:', err);
                const errorMessage = err.response?.data || '댓글 삭제 중 오류가 발생했습니다.';
                setCommentModalMessage(`댓글 삭제 실패: ${errorMessage}`);
                setShowCommentModal(true);
                setShowCommentModalCancel(false);
                setOnCommentModalConfirm(() => () => setShowCommentModal(false));
            }
        });
        setOnCommentModalCancel(() => () => setShowCommentModal(false));
    };

    // 댓글 페이지 변경 핸들러
    const handleCommentPageChange = (newPage) => {
        setCommentCurrentPage(newPage);
    };
    // ====================================================================================
    // 💡💡💡 댓글 기능 관련 함수 추가 끝 💡💡💡
    // ====================================================================================

    if (loading) {
        return <div className="text-center py-8 text-gray-600">로딩 중...</div>;
    }

    if (error) {
        return <div className="text-center py-8 text-red-500">{error}</div>;
    }

    if (!review) {
        return <div className="text-center py-8 text-gray-600">리뷰를 찾을 수 없습니다.</div>;
    }

    return (
        <div className="container mx-auto p-6 bg-white shadow-lg rounded-lg my-8">
            <h1 className="text-4xl font-extrabold mb-6 text-gray-900 border-b-4 border-blue-600 pb-2">
                {review.title}
            </h1>
            <div className="text-gray-600 text-sm mb-6 flex justify-between items-center">
                <span>작성자: {review.memberUsername}</span>
                <span>조회수: {review.viewCount !== null ? review.viewCount : 0}</span>
                <span>작성일: {new Date(review.createdAt).toLocaleDateString()}</span>
            </div>

            <div className="prose max-w-none mb-8 text-gray-800 leading-relaxed"
                 dangerouslySetInnerHTML={{ __html: review.content }}>
            </div>

            {review.photos && review.photos.length > 0 && (
                <div className="mb-8 border-t pt-6">
                    <h2 className="text-2xl font-bold mb-4 text-gray-800">갤러리</h2>
                    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                        {review.photos.map((photo) => (
                            <div key={photo.reviewPhotoId} className="relative group cursor-pointer"
                                 onClick={() => handleImageClick(photo.photoUrl, photo.description)}>
                                <img
                                    src={photo.photoUrl}
                                    alt={photo.description || '리뷰 사진'}
                                    className="w-full h-48 object-cover rounded-lg shadow-md transition-transform transform group-hover:scale-105"
                                />
                                <div
                                    className="absolute inset-0 bg-black bg-opacity-50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity rounded-lg">
                                    <p className="text-white text-center text-sm p-2">
                                        {photo.description || '클릭하여 확대'}
                                    </p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <div className="flex justify-end space-x-4 border-t pt-6 mt-8">
                {/* 현재 로그인한 사용자가 작성자이거나 관리자일 경우 수정/삭제 버튼 표시 */}
                {isAuthenticated && user && (user.memberNo === review.memberNo || user.isAdmin) && (
                    <>
                        <button
                            onClick={() => navigate(`/review/edit/${reviewId}`)}
                            className="px-6 py-2 bg-yellow-500 text-white rounded-md hover:bg-yellow-600 transition duration-300 ease-in-out font-semibold shadow-md"
                        >
                            수정
                        </button>
                        <button
                            onClick={() => {
                                // 삭제 확인 모달 띄우기
                                setShowCommentModal(true);
                                setCommentModalMessage('정말로 이 리뷰를 삭제하시겠습니까?');
                                setShowCommentModalCancel(true);
                                setOnCommentModalConfirm(() => async () => {
                                    setShowCommentModal(false); // 모달 닫기
                                    try {
                                        await axios.delete(`/api/reviews/${reviewId}`, {
                                            headers: { 'Authorization': `Bearer ${token}` }
                                        });
                                        setCommentModalMessage('리뷰가 성공적으로 삭제되었습니다! 🎉');
                                        setShowCommentModal(true);
                                        setShowCommentModalCancel(false);
                                        setOnCommentModalConfirm(() => () => {
                                            setShowCommentModal(false);
                                            navigate('/reviews'); // 목록 페이지로 이동
                                        });
                                    } catch (err) {
                                        console.error('리뷰 삭제 실패:', err);
                                        const errorMessage = err.response?.data || '리뷰 삭제 중 오류가 발생했습니다.';
                                        setCommentModalMessage(`리뷰 삭제 실패: ${errorMessage}`);
                                        setShowCommentModal(true);
                                        setShowCommentModalCancel(false);
                                        setOnCommentModalConfirm(() => () => setShowCommentModal(false));
                                    }
                                });
                                setOnCommentModalCancel(() => () => setShowCommentModal(false));
                            }}
                            className="px-6 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 transition duration-300 ease-in-out font-semibold shadow-md"
                        >
                            삭제
                        </button>
                    </>
                )}
                <button
                    onClick={() => navigate('/reviews')}
                    className="px-6 py-2 bg-gray-600 text-white rounded-md hover:bg-gray-700 transition duration-300 ease-in-out font-semibold shadow-md"
                >
                    목록으로
                </button>
            </div>

            {/* ==================================================================================== */}
            {/* 💡💡💡 댓글 섹션 시작 💡💡💡 */}
            {/* ==================================================================================== */}
            <div className="mt-10 border-t pt-8">
                <h2 className="text-3xl font-bold mb-6 text-gray-800">댓글 ({review.commentCount !== null ? review.commentCount : 0})</h2>

                {/* 댓글 작성 폼 */}
                <form onSubmit={handleCommentSubmit} className="mb-8 p-6 bg-gray-50 rounded-lg shadow-inner">
                    <textarea
                        className="w-full p-4 border border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500 transition-all duration-200 resize-y min-h-[100px] text-gray-800"
                        placeholder={isAuthenticated ? "댓글을 입력하세요..." : "로그인 후 댓글을 작성할 수 있습니다."}
                        value={newCommentContent}
                        onChange={(e) => setNewCommentContent(e.target.value)}
                        rows="4"
                        disabled={!isAuthenticated} // 로그인하지 않으면 비활성화
                    ></textarea>
                    <div className="flex justify-end mt-4">
                        <button
                            type="submit"
                            className={`px-8 py-3 rounded-md font-semibold transition duration-300 ease-in-out ${
                                isAuthenticated ? 'bg-blue-600 text-white hover:bg-blue-700' : 'bg-gray-400 text-gray-200 cursor-not-allowed'
                            }`}
                            disabled={!isAuthenticated}
                        >
                            댓글 등록
                        </button>
                    </div>
                </form>

                {/* 댓글 목록 */}
                <div className="space-y-6">
                    {comments.length === 0 ? (
                        <p className="text-center text-gray-500 text-lg py-8">아직 댓글이 없습니다. 첫 댓글을 작성해 보세요! 😄</p>
                    ) : (
                        comments.map((comment) => (
                            <div key={comment.reviewCommentId} className="p-6 bg-white border border-gray-200 rounded-lg shadow-sm">
                                {editingCommentId === comment.reviewCommentId ? (
                                    // 댓글 수정 폼
                                    <div>
                                        <textarea
                                            className="w-full p-3 border border-gray-300 rounded-md focus:ring-green-500 focus:border-green-500 transition-all duration-200 resize-y min-h-[80px] text-gray-800"
                                            value={editingCommentContent}
                                            onChange={(e) => setEditingCommentContent(e.target.value)}
                                            rows="3"
                                        ></textarea>
                                        <div className="flex justify-end space-x-2 mt-3">
                                            <button
                                                onClick={() => handleEditSubmit(comment.reviewCommentId)}
                                                className="px-5 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 transition duration-200 font-semibold"
                                            >
                                                저장
                                            </button>
                                            <button
                                                onClick={handleCancelEdit}
                                                className="px-5 py-2 bg-gray-400 text-white rounded-md hover:bg-gray-500 transition duration-200 font-semibold"
                                            >
                                                취소
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    // 일반 댓글 보기 모드
                                    <>
                                        <div className="flex justify-between items-center mb-3">
                                            <span className="font-semibold text-blue-700 text-lg">{comment.memberUsername}</span>
                                            <span className="text-gray-500 text-sm">
                                                {new Date(comment.createdAt).toLocaleString()}
                                                {comment.updatedAt && new Date(comment.createdAt).getTime() !== new Date(comment.updatedAt).getTime() && (
                                                    <span className="ml-2 text-gray-400">(수정됨)</span>
                                                )}
                                            </span>
                                        </div>
                                        <p className="text-gray-800 leading-relaxed mb-4">{comment.content}</p>
                                        <div className="flex justify-end space-x-2 items-center text-sm text-gray-600">
                                            <span>👀 {comment.viewCount}</span>
                                            <span>❤️ {comment.likeCount}</span>
                                            {/* 로그인한 사용자 본인 댓글이거나 관리자일 경우 수정/삭제 버튼 표시 */}
                                            {isAuthenticated && user && (user.memberNo === comment.memberNo || user.isAdmin) && (
                                                <>
                                                    <button
                                                        onClick={() => handleEditClick(comment)}
                                                        className="ml-4 px-3 py-1 bg-yellow-500 text-white rounded-md text-xs hover:bg-yellow-600 transition"
                                                    >
                                                        수정
                                                    </button>
                                                    <button
                                                        onClick={() => handleDeleteClick(comment.reviewCommentId)}
                                                        className="px-3 py-1 bg-red-600 text-white rounded-md text-xs hover:bg-red-700 transition"
                                                    >
                                                        삭제
                                                    </button>
                                                </>
                                            )}
                                        </div>
                                    </>
                                )}
                            </div>
                        ))
                    )}
                </div>

                {/* 댓글 페이지네이션 */}
                {commentTotalPages > 1 && (
                    <div className="flex justify-center items-center space-x-2 mt-8">
                        <button
                            onClick={() => handleCommentPageChange(commentCurrentPage - 1)}
                            disabled={commentCurrentPage === 0}
                            className="px-4 py-2 bg-gray-200 rounded-md hover:bg-gray-300 disabled:opacity-50"
                        >
                            이전
                        </button>
                        {[...Array(commentTotalPages).keys()].map((page) => (
                            <button
                                key={page}
                                onClick={() => handleCommentPageChange(page)}
                                className={`px-4 py-2 rounded-md ${
                                    commentCurrentPage === page ? 'bg-blue-600 text-white' : 'bg-gray-200 hover:bg-gray-300'
                                }`}
                            >
                                {page + 1}
                            </button>
                        ))}
                        <button
                            onClick={() => handleCommentPageChange(commentCurrentPage + 1)}
                            disabled={commentCurrentPage === commentTotalPages - 1}
                            className="px-4 py-2 bg-gray-200 rounded-md hover:bg-gray-300 disabled:opacity-50"
                        >
                            다음
                        </button>
                    </div>
                )}
            </div>
            {/* ==================================================================================== */}
            {/* 💡💡💡 댓글 섹션 끝 💡💡💡 */}
            {/* ==================================================================================== */}

            {/* 💡 이미지 확대 모달 - 기존 코드 유지 */}
            {showImageModal && (
                <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
                    <div className="relative bg-white rounded-lg p-4 max-w-4xl w-full max-h-[90vh] flex flex-col items-center">
                        <button
                            onClick={handleCloseImageModal}
                            className="absolute top-2 right-2 text-gray-800 text-3xl font-bold p-2 rounded-full bg-gray-200 hover:bg-gray-300 z-10"
                        >
                            &times;
                        </button>
                        <div className="flex-grow flex items-center justify-center w-full min-h-0">
                            <img
                                src={modalImageUrl}
                                alt={modalImageDescription || "확대 이미지"}
                                className="max-w-full max-h-[70vh] object-contain rounded-lg shadow-md"
                            />
                        </div>
                        <p className="flex-shrink-0 mt-4 text-gray-700 text-center text-base font-medium px-4 py-2">
                            {modalImageDescription || "설명 없음"}
                        </p>
                    </div>
                </div>
            )}

            {/* 💡 댓글 관련 커스텀 모달 (CustomModal) */}
            {showCommentModal && (
                <CustomModal
                    message={commentModalMessage}
                    onConfirm={onCommentModalConfirm}
                    onCancel={onCommentModalCancel}
                    showCancel={showCommentModalCancel}
                />
            )}
        </div>
    );
}

export default ReviewDetail;
